import{_ as l,c as a,o as e,a4 as i}from"./chunks/framework.4aTu-Nia.js";const f=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"project/architecture.md","filePath":"project/architecture.md"}'),t={name:"project/architecture.md"},o=i('<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>[toc]</p><blockquote><p>软件结构是指软件系统的基本结构，以及创建这种结构和系统的约束。每个结构包括软件元素、元素之间的关系，以及元素和关系的属性。软件系统架构是一个比喻，类似于建筑物的架构。它作为系统和开发项目的蓝图，列出了设计团队需要执行的任务。 - 维基百科</p></blockquote><blockquote><p>架构是指体现在它的组件中的一个系统的基本组织、组织之间的关系、组织与环境的关系及指导其设计和发展的原则。 - IEEE</p></blockquote><h2 id="价值" tabindex="-1">价值： <a class="header-anchor" href="#价值" aria-label="Permalink to &quot;价值：&quot;">​</a></h2><ul><li>工程 巨石应用</li><li>产品 组合</li></ul><p><img src="https://ucc.alicdn.com/pic/developer-ecology/0c84fbd3fd7840a590a3a6228efb6f96.png" alt="0c84fbd3fd7840a590a3a6228efb6f96.png (1080×860)"></p><p><img src="https://pic4.zhimg.com/80/v2-c3c69d4a03f76d7adc60d6225e605bc3_720w.png" alt="v2-c3c69d4a03f76d7adc60d6225e605bc3_720w.png (720×323)"></p><ol><li>架构是系统实现的蓝图</li><li>架构是沟通协作的基础 <ul><li>理解对齐</li><li>工作量化</li><li>标准术语</li><li>言之有物</li><li>知识沉淀 &amp; 新人培训</li></ul></li><li>架构决定了产品质量</li></ol><h2 id="寻找架构需求" tabindex="-1">寻找架构需求 <a class="header-anchor" href="#寻找架构需求" aria-label="Permalink to &quot;寻找架构需求&quot;">​</a></h2><ol><li>考虑多方利益，折中</li><li>寻找架构关注点：性能、安全、平台化、代码维护、用户体验</li><li>列出风险点</li></ol><h2 id="评判架构" tabindex="-1">评判架构 <a class="header-anchor" href="#评判架构" aria-label="Permalink to &quot;评判架构&quot;">​</a></h2><p>合理、合适、可行、可落地</p><h2 id="架构原则-设计原则" tabindex="-1">架构原则/设计原则 <a class="header-anchor" href="#架构原则-设计原则" aria-label="Permalink to &quot;架构原则/设计原则&quot;">​</a></h2><h2 id="架构模式" tabindex="-1">架构模式 <a class="header-anchor" href="#架构模式" aria-label="Permalink to &quot;架构模式&quot;">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/260068315" target="_blank" rel="noreferrer">架构制图：工具与方法论 - 知乎</a></p><p><a href="https://www.yuque.com/kuitos/gky7yw/gesexv" target="_blank" rel="noreferrer">Why Not Iframe · 语雀</a></p><p>散弹式架构 - jQuery</p><ol><li>多页面，函数分散，DOM 处理逻辑分散</li><li>问题，维护失控，需整体梳理</li><li>如何降低弊端出现 <ol><li>统一交互处理</li><li>按页面拆分脚本</li><li>id/class 唯一性</li></ol></li></ol><p>组件化架构</p><ol><li>分层/分类 <ol><li>基础 UI 组件（最小单元） <ol><li>原则：独立存在，可以共享配置，但不能互相依赖</li></ol></li><li>复合组件（组合）</li><li>业务组件（数据请求、处理）</li></ol></li><li>问题 1. 2. 过度设计 1. 在可预见未来（几周），有重用需求</li></ol><p>关注重点：在什么样的上下文，外部依赖是什么，提供什么功能</p><p>约束、规律，建模</p>',23),r=[o];function c(h,p,n,d,s,u){return e(),a("div",null,r)}const b=l(t,[["render",c]]);export{f as __pageData,b as default};
